"""Independent synthetic byte-oracle controls; no native/process fixture."""
from pathlib import Path
import json
import struct
import sys
import unittest
import tempfile
from unittest.mock import patch

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "integration"))
from recorder_observer import AcceptanceObserver, decode, InvalidTrace, NONE

CAPTURE = "00000000-0000-0000-0000-000000000001"
RAW = "00000000-0000-0000-0000-000000000002"


def fixture():
    # Hand-constructed timeline from the capture/queue/durability contract, not
    # generated by the C++ recorder or by parsing the decoder's own constants.
    events = []
    counts = [0] * 4

    def add(lane, kind, item, begin, end, a=0, b=0):
        event = [lane, counts[lane], kind, item, begin, end, begin, end, a, b, 0]
        counts[lane] += 1
        events.append(event)
        return event

    add(0, 1, NONE, 1, 2, 32, 0)
    add(1, 2, 0, 3, 4, 0, 0)
    for kind, begin, end in [(3, 10, 20), (4, 21, 30), (5, 31, 40), (6, 41, 60)]:
        add(1, kind, 0, begin, end)
    add(1, 7, 0, 61, 62, 1, 0)
    add(1, 8, 0, 63, 70)
    add(2, 10, NONE, 30, 90)
    add(2, 11, 0, 100, 1000)
    add(2, 44, 0, 101, 102, 0, 1)
    add(2, 45, 0, 103, 104, 1, 1)
    add(2, 46, 0, 105, 106, 0, 0)
    add(2, 12, 0, 110, 800)
    add(2, 20, 0, 120, 790)
    for i, kind in enumerate(range(21, 35)):
        add(2, kind, 0, 125 + i * 40, 150 + i * 40)
    add(2, 13, 0, 810, 840)
    add(2, 14, 0, 850, 900)
    add(2, 15, 0, 910, 950)
    add(2, 43, NONE, 1010, 1011)
    add(1, 42, NONE, 1020, 1021)
    add(3, 50, NONE, 1100, 1101, 1090, 1000)
    header = dict(version=1, record_bytes=88, workload="actual-acceptance", clock="steady_ns_since_observer_start",
                  thread_cpu_clock="thread_duration_only", origin_ns=123456, snapshot_ns=2000,
                  capture_ordinal=3, capture_selected=True, capture_id=CAPTURE, raw_id=RAW,
                  schema=1, streams=1, source_paced=0, queue_capacity=32, enqueue_budget_ns=50000000,
                  counts=counts, exported_counts=counts[:], dropped=[0, 0, 0, 0],
                  limits=[4096, 8192, 32768, 1024], observer_emission_cpu_ns=[1, 1, 1, 1],
                  clock_error=False, identity_error=False, observer_error=False, expired=False, first_failure_pending=False,
                  workers_running=[False, False], first_failure=None, output_rejected=False,
                  queue_sample_scope="separate_metric_lock_interval_not_linearization",
                  wait_attribution="off_cpu_or_io_not_discriminated",
                  observer_qualification="UNQUALIFIED_REQUIRES_MATCHED_NATIVE_CONTROL")
    return header, events


def encode(header, events):
    # Wire bytes specified independently; reject a decoder silently accepting a
    # changed endianness, word count or sliced JSON as a valid observer record.
    payload = json.dumps(header, separators=(",", ":")).encode()
    return b"MREC0001" + struct.pack("<Q", len(payload)) + payload + b"".join(
        struct.pack("<11Q", *event) for event in sorted(events, key=lambda e: (e[0], e[1])))


class RecorderObserverTests(unittest.TestCase):
    def decode(self, header, events):
        return decode(encode(header, events), capture_id=CAPTURE, raw_id=RAW)

    def reject(self, mutation, message):
        header, events = fixture()
        mutation(header, events)
        with self.assertRaisesRegex(InvalidTrace, message):
            self.decode(header, events)

    def test_complete_scope_has_no_causality_durability_or_cost_promotion(self):
        result = self.decode(*fixture())
        self.assertEqual(result["status"], "COVERAGE_CHECKED")
        self.assertEqual(result["fully_accounted_callbacks"], 1)
        self.assertEqual(result["failed_admissions"], 0)
        self.assertEqual(result["historical_cause"], "UNKNOWN")
        self.assertEqual(result["observer"], "UNQUALIFIED")
        self.assertIsNone(result["recovered_records"])
        self.assertNotIn(CAPTURE, json.dumps(result))

    def test_omitted_post_callback_and_store_stage_fail_even_if_counts_resealed(self):
        for kind in (11, 13, 14, 15, 20, 21, 24, 32, 34):
            with self.subTest(kind=kind):
                header, events = fixture()
                events = [e for e in events if e[2] != kind]
                lane = [e for e in events if e[0] == 2]
                for i, event in enumerate(lane):
                    event[1] = i
                header["counts"][2] -= 1
                header["exported_counts"][2] -= 1
                with self.assertRaisesRegex(InvalidTrace, "omitted"):
                    self.decode(header, events)

    def test_whole_writer_item_cannot_disappear_behind_resealed_counts(self):
        header, events = fixture()
        events = [e for e in events if e[0] != 2 or e[2] in (10, 43)]
        for i, event in enumerate(e for e in events if e[0] == 2):
            event[1] = i
        header["counts"][2] = header["exported_counts"][2] = 2
        with self.assertRaisesRegex(InvalidTrace, "unmatched accepted item"):
            self.decode(header, events)

    def test_missing_duplicate_and_foreign_lane_records_fail(self):
        self.reject(lambda h, e: e.pop(10), "truncated/extra")
        self.reject(lambda h, e: e.append(e[10][:]), "truncated/extra")
        self.reject(lambda h, e: e[10].__setitem__(1, 0), "order")
        self.reject(lambda h, e: e[10].__setitem__(0, 1), "order|bound")

    def test_exact_capture_raw_workload_and_clock_are_required(self):
        for key, value in [("capture_id", RAW), ("raw_id", CAPTURE), ("capture_ordinal", 2),
                           ("schema", 2), ("source_paced", 1), ("clock", "realtime"),
                           ("queue_capacity", 64), ("enqueue_budget_ns", 100000000)]:
            with self.subTest(key=key):
                self.reject(lambda h, e: h.__setitem__(key, value), "identity|workload|clock|contract")

    def test_store_misattribution_and_overlap_are_rejected(self):
        self.reject(lambda h, e: next(x for x in e if x[2] == 24).__setitem__(3, 99), "omitted")
        self.reject(lambda h, e: next(x for x in e if x[2] == 24).__setitem__(5, 700), "overlapping")
        self.reject(lambda h, e: next(x for x in e if x[2] == 15).__setitem__(5, 1100), "post-callback")

    def test_pending_expired_workers_and_declared_drops_are_never_complete(self):
        for field, value in [("expired", True), ("workers_running", [False, True]),
                             ("dropped", [0, 0, 1, 0])]:
            header, events = fixture()
            header[field] = value
            result = self.decode(header, events)
            self.assertEqual(result["status"], "INCOMPLETE")
            self.assertEqual(result["observer"], "UNQUALIFIED")
        header, events = fixture()
        service = next(e for e in events if e[2] == 11)
        service[5] = service[7] = NONE
        service[10] = 2
        self.assertEqual(self.decode(header, events)["pending_spans"], 1)

    def test_first_failure_survives_declared_output_exhaustion(self):
        header, events = fixture()
        header["first_failure"] = [1, 0, 40, 1, 1500, 1500, 0, 0, 35, 1, 4]
        header["output_rejected"] = True
        header["exported_counts"] = [0, 0, 0, 0]
        result = self.decode(header, [])
        self.assertTrue(result["first_failure_retained"])
        self.assertEqual(result["status"], "INCOMPLETE")
        self.assertIsNone(result["recovered_records"])

    def test_unreported_first_failure_loss_and_fabricated_qualification_fail(self):
        self.reject(lambda h, e: h.__setitem__("first_failure", [1, 0, 40, 1, 1500, 1500,
                    0, 0, 35, 1, 4]), "missing first failure")
        self.reject(lambda h, e: h.__setitem__("observer_qualification", "PASS"), "qualification")

    def test_queue_high_water_and_long_callback_are_not_failed_admission(self):
        header, events = fixture()
        # All wall/CPU clocks scaled equally; one callback now exceeds50ms.
        for event in events:
            for field in (4, 5, 6, 7):
                event[field] *= 100000
            if event[2] == 50:
                event[8] *= 100000
        header["snapshot_ns"] *= 100000
        sample = next(e for e in events if e[2] == 44)
        sample[9] = 32
        result = self.decode(header, events)
        self.assertEqual(result["failed_admissions"], 0)

    def test_source_identity_and_resource_window_negatives(self):
        self.reject(lambda h, e: next(x for x in e if x[2] == 7).__setitem__(9, 5), "identity/order")
        self.reject(lambda h, e: next(x for x in e if x[2] == 50).__setitem__(8, 3000), "resource window")

    def test_byte_bounds_extra_truncated_and_malformed_header(self):
        header, events = fixture()
        valid = encode(header, events)
        for data in (valid[:-1], valid + b"x", b"MREC0001" + struct.pack("<Q", 99999),
                     b"MREC0001" + struct.pack("<Q", 1) + b"{"):
            with self.assertRaises(InvalidTrace):
                decode(data, capture_id=CAPTURE, raw_id=RAW)

    def test_typed_header_and_control_records_cannot_impersonate_actual_acceptance(self):
        for key, value in [("version", True), ("streams", True), ("source_paced", False),
                           ("workload", "observer-self-test")]:
            with self.subTest(key=key):
                self.reject(lambda h, e: h.__setitem__(key, value), "typed|workload")
        header, events = fixture()
        valid = encode(header, events)
        size, = struct.unpack_from("<Q", valid, 8)
        duplicate = valid[16:16 + size][:-1] + b',"schema":1}'
        data = valid[:8] + struct.pack("<Q", len(duplicate)) + duplicate + valid[16 + size:]
        with self.assertRaisesRegex(InvalidTrace, "invalid header"):
            decode(data, capture_id=CAPTURE, raw_id=RAW)

    @staticmethod
    def observer(root):
        observer = AcceptanceObserver.__new__(AcceptanceObserver)
        observer.output = root / "evidence"
        observer.output.mkdir()
        observer.root = root
        trace = observer.output / "daemon-0"
        trace.mkdir()
        observer.runs = [trace]
        observer.identity = dict(capture_id=CAPTURE, raw_id=RAW)
        observer.errors = []
        return observer

    def test_export_wait_requires_complete_ack_and_exact_linkage(self):
        with tempfile.TemporaryDirectory() as path:
            observer = self.observer(Path(path))
            data = encode(*fixture())
            class Process:
                def send_signal(self, value):
                    (observer.runs[0] / "snapshot-0.bin").write_bytes(data)
                def poll(self):
                    return None
            result = observer.flush(Process())
            self.assertEqual(result["fully_accounted_callbacks"], 1)
            self.assertNotIn(CAPTURE, (observer.output / "latest-decoded.json").read_text())
            observer.identity["raw_id"] = CAPTURE
            class WrongCapture(Process):
                def send_signal(self, value):
                    (observer.runs[0] / "snapshot-1.bin").write_bytes(data)
            with self.assertRaisesRegex(InvalidTrace, "identity mismatch"):
                observer.flush(WrongCapture())

    def test_missing_export_ack_is_bounded_without_retiring_another_owner(self):
        with tempfile.TemporaryDirectory() as path:
            observer = self.observer(Path(path))
            class Process:
                def send_signal(self, value):
                    pass
                def poll(self):
                    return None
            clock = [0]
            def wait(seconds):
                clock[0] += seconds
            with self.assertRaisesRegex(InvalidTrace, "acknowledgement unavailable"):
                observer.flush(Process(), now=lambda: clock[0], wait=wait)
            self.assertLessEqual(clock[0], 2.02)

    def test_secondary_retention_fault_preserves_primary_and_exports_no_exception(self):
        with tempfile.TemporaryDirectory() as path:
            root = Path(path)
            observer = self.observer(root)
            (root / "Project.mantis").mkdir()
            primary = AssertionError("original acceptance predicate")
            with patch("shutil.copytree", side_effect=RuntimeError("PRIVATE_FAULT_SENTINEL")):
                observer.retain([], primary)
            record = (observer.output / "retention-unavailable.json").read_text()
            self.assertNotIn("PRIVATE_FAULT_SENTINEL", record)
            self.assertIn("UNQUALIFIED", record)
            self.assertEqual(str(primary), "original acceptance predicate")

    def test_project_symlink_is_not_followed_and_retirement_is_recorded(self):
        with tempfile.TemporaryDirectory() as path:
            root = Path(path)
            observer = self.observer(root)
            project = root / "Project.mantis"
            project.mkdir()
            (project / "not-a-capture").symlink_to(observer.output, target_is_directory=True)
            observer.retain([], AssertionError("original"))
            self.assertFalse((observer.output / "failed-project").exists())
            self.assertTrue((observer.output / "retention-unavailable.json").exists())


if __name__ == "__main__":
    unittest.main()
